export type ToolResult =
  | { status: "success"; output: string; details?: Record<string, string | number> }
  | { status: "error"; message: string };

export type TextTransform = "upper" | "lower" | "title";

export function titleCase(text: string): string {
  return text.replace(/\S+/g, (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
}

export function countWords(text: string): number {
  const trimmed = text.trim();
  if (trimmed.length === 0) return 0;
  return trimmed.split(/\s+/).length;
}

export function applyTextTransform(input: string, transform: TextTransform): ToolResult {
  if (input.length === 0) return { status: "error", message: "Paste some text before running the transformation." };
  let value = input;
  if (transform === "upper") value = input.toUpperCase();
  else if (transform === "lower") value = input.toLowerCase();
  else value = titleCase(input);
  return {
    status: "success",
    output: value,
    details: { characters: input.length, words: countWords(input) },
  };
}

export type DataTool = "json" | "encode" | "decode";

export function runDataTool(input: string, tool: DataTool): ToolResult {
  if (tool === "json") {
    let parsed: unknown;
    try {
      parsed = JSON.parse(input);
    } catch (err) {
      const msg = err instanceof Error ? err.message : "invalid JSON";
      return { status: "error", message: `Malformed JSON: ${msg}` };
    }
    return { status: "success", output: JSON.stringify(parsed, null, 2) };
  }

  if (tool === "encode") {
    if (input.length === 0) return { status: "error", message: "Enter query text to encode." };
    const parts = input
      .replace(/^[?&]/, "")
      .split("&")
      .map((pair) => {
        const idx = pair.indexOf("=");
        if (idx === -1) {
          return encodeURIComponent(pair);
        }
        return `${encodeURIComponent(pair.slice(0, idx))}=${encodeURIComponent(pair.slice(idx + 1))}`;
      })
      .join("&");
    return { status: "success", output: parts };
  }

  const pairs = input
    .replace(/^[?&]/, "")
    .split("&")
    .filter((part) => part.length > 0)
    .map((pair) => {
      const idx = pair.indexOf("=");
      if (idx === -1) {
        const decoded = decodeURIComponent(pair);
        return { key: decoded, value: "" };
      }
      const key = decodeURIComponent(pair.slice(0, idx));
      const value = decodeURIComponent(pair.slice(idx + 1));
      return { key, value };
    });
  if (pairs.length === 0) return { status: "error", message: "Enter a query string to decode." };
  const obj: Record<string, string> = {};
  for (const p of pairs) obj[p.key] = p.value;
  return { status: "success", output: JSON.stringify(obj, null, 2), details: { params: pairs.length } };
}

export function analyzeHtml(input: string): ToolResult {
  if (input.trim().length === 0) return { status: "error", message: "Paste an HTML document to analyze." };
  const doc = input.toLowerCase();
  const titleMatch = input.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const descMatch = input.match(/<meta[^>]+name=["']description["'][^>]+content=["']([\s\S]*?)["']/i) ||
    input.match(/<meta[^>]+content=["']([\s\S]*?)["'][^>]+name=["']description["']/i);
  const h1Count = (doc.match(/<h1[\s>]/g) || []).length;
  const h2Count = (doc.match(/<h2[\s>]/g) || []).length;
  const h3Count = (doc.match(/<h3[\s>]/g) || []).length;
  const links = (input.match(/<a[\s>][^>]*href=["'][^"']*["']/gi) || []).length;
  const images = (input.match(/<img[\s>][^>]*>/gi) || []);
  const imgsWithAlt = images.filter((tag) => /alt=["'][^"']*["']/.test(tag)).length;
  const lines: string[] = [];
  lines.push(`Title: ${titleMatch ? titleMatch[1].trim() : "(missing)"}`);
  lines.push(`Meta description: ${descMatch ? descMatch[1].trim() : "(missing)"}`);
  lines.push(`Headings: ${h1Count} h1, ${h2Count} h2, ${h3Count} h3`);
  lines.push(`Links: ${links}`);
  lines.push(`Images: ${images.length} total, ${imgsWithAlt} with alt text`);
  return {
    status: "success",
    output: lines.join("\n"),
    details: { title: titleMatch ? 1 : 0, description: descMatch ? 1 : 0, links, images: images.length },
  };
}

export function inspectMedia(input: string): ToolResult {
  if (input.trim().length === 0) return { status: "error", message: "Paste a data URL or SVG text to inspect." };

  const trimmed = input.trim();

  if (trimmed.startsWith("<svg") || trimmed.includes("<svg")) {
    const svg = new (globalThis as unknown as { DOMParser: new () => { parseFromString(s: string, t: string): Document } }).DOMParser().parseFromString(trimmed, "image/svg+xml");
    const root = svg.querySelector("svg");
    if (!root) return { status: "error", message: "Could not parse SVG markup." };
    const vb = root.getAttribute("viewBox");
    const width = root.getAttribute("width") || (vb ? vb.split(/[\s,]+/)[2] : "") || "";
    const height = root.getAttribute("height") || (vb ? vb.split(/[\s,]+/)[3] : "") || "";
    const text: string[] = ["Type: SVG vector"];
    if (width) text.push(`Width: ${width}`);
    if (height) text.push(`Height: ${height}`);
    text.push(`Bytes: ${new Blob([trimmed]).size}`);
    return { status: "success", output: text.join("\n") };
  }

  const dataMatch = trimmed.match(/^data:([^;,]+)?(;base64)?,([\s\S]*)$/);
  if (!dataMatch) return { status: "error", message: "Provide a data: URL or SVG text." };
  const mime = dataMatch[1] || "unknown";
  const isBase64 = Boolean(dataMatch[2]);
  const payload = dataMatch[3].replace(/\s+/g, "");
  let bytes = 0;
  try {
    bytes = isBase64
      ? Math.floor(((payload.length * 3) / 4) - (payload.endsWith("==") ? 2 : payload.endsWith("=") ? 1 : 0))
      : new TextEncoder().decode(new Uint8Array(0)).length === 0 ? decodeURIComponent(payload).length : payload.length;
  } catch {
    bytes = payload.length;
  }
  return {
    status: "success",
    output: `Type: ${mime}\nEncoding: ${isBase64 ? "base64" : "text"}\nSize: ${bytes} bytes`,
    details: { type: mime, bytes },
  };
}

export function buildSocialPreview(title: string, description: string, url: string): ToolResult {
  const t = title.trim();
  const d = description.trim();
  const u = url.trim();
  if (!t || !d || !u) return { status: "error", message: "Fill in title, description, and URL." };
  if (!/^https?:\/\//i.test(u)) return { status: "error", message: "URL must start with http:// or https://." };
  const titleTrunc = t.length > 60 ? t.slice(0, 57) + "…" : t;
  const descTrunc = d.length > 160 ? d.slice(0, 157) + "…" : d;
  return {
    status: "success",
    output: [
      `Title (${titleTrunc.length}/60): ${titleTrunc}`,
      `Description (${descTrunc.length}/160): ${descTrunc}`,
      `URL: ${u}`,
      `Truncations: ${t.length > 60 || d.length > 160 ? "yes" : "no"}`,
    ].join("\n"),
  };
}

export function parseSocialFallback(input: string): { title: string; description: string; url: string } {
  const trimmed = input.trim();
  if (trimmed.startsWith("{")) {
    try {
      const obj: unknown = JSON.parse(trimmed);
      if (obj && typeof obj === "object") {
        const record = obj as Record<string, unknown>;
        return {
          title: typeof record.title === "string" ? record.title : "",
          description: typeof record.description === "string" ? record.description : "",
          url: typeof record.url === "string" ? record.url : "",
        };
      }
    } catch {
      // fall through
    }
  }
  return { title: "", description: "", url: "" };
}

