import { DOM } from "@anikitenko/fdo-sdk";
import css from "./styles.css";
import { renderDashboard } from "./features/dashboard/render";
import { renderLibrary } from "./features/library/render";
import { renderJsonWorkspace } from "./features/json/render";
import { renderSpaceDialog } from "./features/space/render";
import { renderCategoryWorkspace } from "./features/category/render";

export function render(json: unknown = null): string {
  const dom = new DOM();
  const shellClass = dom.createClassFromStyle(css.shell);
  const dashboardClass = dom.createClassFromStyle(css.dashboard);
  const cardClass = dom.createClassFromStyle(css.card);
  const libraryClass = dom.createClassFromStyle(css.library);
  const workspaceClass = dom.createClassFromStyle(css.workspace);
  const resultClass = dom.createClassFromStyle(css.result);
  const dockClass = dom.createClassFromStyle(css.dock);

  const root = dom.createElement(
    "div",
    { "data-role": "tool-workbench" },
    renderDashboard(dom, cardClass, dashboardClass),
    renderJsonWorkspace(dom, workspaceClass, resultClass),
    renderCategoryWorkspace(dom, workspaceClass, resultClass, "text"),
    renderCategoryWorkspace(dom, workspaceClass, resultClass, "data"),
    renderCategoryWorkspace(dom, workspaceClass, resultClass, "seo"),
    renderCategoryWorkspace(dom, workspaceClass, resultClass, "images"),
    renderCategoryWorkspace(dom, workspaceClass, resultClass, "social"),
    renderLibrary(dom, libraryClass),
    renderSpaceDialog(dom),
    dom.createElement("div", { class: dockClass })
  );

  return dom.renderHTML(root);
}

export function renderCategory(category: string): string {
  const dom = new DOM();
  const workspaceClass = dom.createClassFromStyle(css.workspace);
  const resultClass = dom.createClassFromStyle(css.result);
  const root = dom.createElement("div", {}, renderCategoryWorkspace(dom, workspaceClass, resultClass, category));
  return dom.renderHTML(root);
}

