import css from "../../styles.css";

export function renderDashboard(title?: string, subtitle?: string, classes?: Record<string, string>): string {
  const headingTitle = title ?? "Workbench";
  const headingSubtitle = subtitle ?? "Everything you need for a small task.";
  const tileClass = classes?.tile ?? "tile";
  const tileIconClass = classes?.tileIcon ?? "tile-icon";
  const tileLabelClass = classes?.tileLabel ?? "tile-label";

  const tile = (role: string, modifier: string, iconClass: string, icon: string, label: string): string =>
    `<button type="button" data-role="${role}" class="${tileClass} ${tileClass}-${modifier}">` +
    `<span class="${tileIconClass} ${iconClass}" aria-hidden="true">${icon}</span>` +
    `<span class="${tileLabelClass}">${label}</span></button>`;

  const libraryButton =
    `<button type="button" data-role="tool-library-button" class="${tileClass} ${tileClass}-wide">` +
    `<span class="${tileIconClass} icon-amber" aria-hidden="true">M</span>` +
    `<span class="${tileLabelClass}">My packs and favourites</span></button>`;

  const spaceButton =
    `<button type="button" data-role="tool-space-button" class="${tileClass} ${tileClass}-more">` +
    `<span class="${tileIconClass} icon-slate" aria-hidden="true">...</span></button>`;

  const categoryTiles =
    tile("tool-card-text", "text", "icon-peach", "T", "Text &amp; Content") +
    tile("tool-card-data", "data", "icon-sage", "&lt;/&gt;", "Development &amp; Data") +
    tile("tool-card-seo", "seo", "icon-mint", "#", "Web &amp; SEO") +
    tile("tool-card-images", "images", "icon-rose", "&#9634;", "Images &amp; Media") +
    tile("tool-card-social", "social", "icon-lavender", "&#9679;", "Social &amp; Platforms");

  const jsonTile =
    tile("tool-card-json", "json", "icon-cream", "{ }", "JSON Formatter");

  return `<div data-role="tool-workbench" class="${css.shell}">
    <header class="brand" data-role="tool-brand">
      <span class="brand-mark">W</span>
      <span class="brand-name">webtools</span>
    </header>
    <section class="dashboard" data-role="tool-dashboard">
      <div class="dashboard-heading">
        <h1>${headingTitle}</h1>
        <p>${headingSubtitle}</p>
      </div>
      ${libraryButton}
      ${spaceButton}
      ${categoryTiles}
      ${jsonTile}
    </section>
    <footer class="dock" data-role="tool-dock">
      <span class="dock-label">Local webmaster tools</span>
    </footer>
  </div>`;
}

