import css from "../../styles.css";

export type CategoryKey = "text" | "data" | "seo" | "images" | "social";

const CATEGORY_LABELS: Record<CategoryKey, string> = {
  text: "Text & Content",
  data: "Development & Data",
  seo: "Web & SEO",
  images: "Images & Media",
  social: "Social & Platforms",
};

const CATEGORY_TILES: Record<CategoryKey, { icon: string; color: string; label: string }> = {
  text: { icon: "fa-font", color: "#e8c39e", label: "Text & Content" },
  data: { icon: "fa-code", color: "#a8d5ba", label: "Development & Data" },
  seo: { icon: "fa-sitemap", color: "#a3c8e0", label: "Web & SEO" },
  images: { icon: "fa-image", color: "#c9a8d4", label: "Images & Media" },
  social: { icon: "fa-share-nodes", color: "#e0a8a8", label: "Social & Platforms" },
};

interface CategoryConfig {
  key: CategoryKey;
  title: string;
  inputLabel: string;
  inputPlaceholder: string;
  inputType: "textarea" | "text" | "select";
  selectOptions?: { value: string; label: string }[];
  actionLabel: string;
  resultHint: string;
}

function getCategoryConfig(key: CategoryKey): CategoryConfig {
  switch (key) {
    case "text":
      return {
        key: "text",
        title: "Text & Content",
        inputLabel: "Text to transform",
        inputPlaceholder: "Paste or type your text here…",
        inputType: "textarea",
        selectOptions: [
          { value: "upper", label: "UPPERCASE" },
          { value: "lower", label: "lowercase" },
          { value: "title", label: "Title Case" },
        ],
        actionLabel: "Transform Text",
        resultHint: "Result and character/word counts will appear here.",
      };
    case "data":
      return {
        key: "data",
        title: "Development & Data",
        inputLabel: "Input data",
        inputPlaceholder: 'Paste JSON, or URL query text… e.g. {"a":1}',
        inputType: "textarea",
        selectOptions: [
          { value: "json", label: "Format JSON" },
          { value: "encode", label: "URL-encode" },
          { value: "decode", label: "URL-decode" },
        ],
        actionLabel: "Run Tool",
        resultHint: "Formatted JSON or encoded/decoded output will appear here.",
      };
    case "seo":
      return {
        key: "seo",
        title: "Web & SEO",
        inputLabel: "HTML source",
        inputPlaceholder: "Paste an HTML page or fragment to analyze…",
        inputType: "textarea",
        actionLabel: "Analyze HTML",
        resultHint: "Title, description, headings, links and image-alt coverage will appear here.",
      };
    case "images":
      return {
        key: "images",
        title: "Images & Media",
        inputLabel: "Data URL or SVG markup",
        inputPlaceholder: "Paste a data: URL or raw SVG text…",
        inputType: "textarea",
        actionLabel: "Inspect Media",
        resultHint: "Media type, dimensions and size will appear here.",
      };
    case "social":
      return {
        key: "social",
        title: "Social & Platforms",
        inputLabel: "JSON fallback (optional)",
        inputPlaceholder: '{"title":"…","description":"…","url":"https://…"}',
        inputType: "text",
        actionLabel: "Build Preview",
        resultHint: "A local social-preview summary will appear here.",
      };
  }
}

function renderCategoryWorkspaceInner(
  key: CategoryKey,
  classes: Record<string, string>
): string {
  const config = getCategoryConfig(key);
  const tile = CATEGORY_TILES[key];

  const workspaceClass = classes.workspace ?? "workspace";
  const resultClass = classes.result ?? "result";
  const cardClass = classes.card ?? "card";

  // --- input area ---
  let inputMarkup: string;

  if (key === "social") {
    // Social has three named fields plus a JSON fallback in the first input.
    inputMarkup = `
      <label class="tw-label" for="tool-category-input">
        <span class="tw-field-label">JSON fallback (optional)</span>
        <input
          id="tool-category-input"
          data-role="tool-category-input"
          name="json-fallback"
          type="text"
          class="tw-input"
          placeholder='{"title":"…","description":"…","url":"https://…"}'
        />
      </label>
      <label class="tw-label" for="tool-category-title">
        <span class="tw-field-label">Title</span>
        <input
          id="tool-category-title"
          name="title"
          type="text"
          class="tw-input"
          placeholder="Your page title"
        />
      </label>
      <label class="tw-label" for="tool-category-description">
        <span class="tw-field-label">Description</span>
        <textarea
          id="tool-category-description"
          name="description"
          rows="2"
          class="tw-input tw-input-area"
          placeholder="A short description of your page"
        ></textarea>
      </label>
      <label class="tw-label" for="tool-category-url">
        <span class="tw-field-label">URL</span>
        <input
          id="tool-category-url"
          name="url"
          type="text"
          class="tw-input"
          placeholder="https://example.com"
        />
      </label>
    `;
  } else if (config.selectOptions) {
    const options = config.selectOptions
      .map((o) => `<option value="${o.value}">${o.label}</option>`)
      .join("");
    inputMarkup = `
      <label class="tw-label" for="tool-category-select">
        <span class="tw-field-label">Operation</span>
        <select id="tool-category-select" data-role="tool-category-select" class="tw-select">
          ${options}
        </select>
      </label>
      <label class="tw-label" for="tool-category-input">
        <span class="tw-field-label">${config.inputLabel}</span>
        <textarea
          id="tool-category-input"
          data-role="tool-category-input"
          rows="6"
          class="tw-input tw-input-area"
          placeholder="${config.inputPlaceholder}"
        ></textarea>
      </label>
    `;
  } else {
    inputMarkup = `
      <label class="tw-label" for="tool-category-input">
        <span class="tw-field-label">${config.inputLabel}</span>
        <textarea
          id="tool-category-input"
          data-role="tool-category-input"
          rows="6"
          class="tw-input tw-input-area"
          placeholder="${config.inputPlaceholder}"
        ></textarea>
      </label>
    `;
  }

  return `
    <div
      class="${workspaceClass}"
      data-role="tool-category-workspace"
      data-tool-category="${key}"
      data-state="idle"
    >
      <div class="tw-category-header">
        <button
          type="button"
          data-role="tool-category-back"
          class="tw-back-btn"
          aria-label="Back to dashboard"
        >
          <i class="fa-solid fa-arrow-left" aria-hidden="true"></i>
          <span>Dashboard</span>
        </button>
        <div class="tw-category-title-block">
          <span class="tw-folder-icon" style="background:${tile.color};">
            <i class="fa-solid ${tile.icon}" aria-hidden="true"></i>
          </span>
          <h2 class="tw-category-title">${config.title}</h2>
        </div>
      </div>

      <form class="pure-form pure-form-stacked tw-category-form" data-category="${key}">
        ${inputMarkup}
        <div class="tw-category-actions">
          <button
            type="button"
            data-role="tool-category-action"
            class="pure-button pure-button-primary tw-action-btn"
          >
            <i class="fa-solid fa-bolt" aria-hidden="true"></i>
            ${config.actionLabel}
          </button>
        </div>
      </form>

      <div
        data-role="tool-category-result"
        data-state="idle"
        class="${resultClass} tw-result"
        aria-live="polite"
      >
        <span class="tw-result-hint">${config.resultHint}</span>
      </div>
    </div>
  `;
}

export function renderCategoryWorkspace(
  category: string,
  classes?: Record<string, string>
): string {
  const key = (["text", "data", "seo", "images", "social"] as const).includes(
    category as CategoryKey
  )
    ? (category as CategoryKey)
    : "text";

  const safeClasses = classes ?? {};
  const inner = renderCategoryWorkspaceInner(key, safeClasses);

  const cardClass = safeClasses.card ?? "card";
  return `
    <div class="${cardClass} tw-category-card" data-tool-category="${key}">
      ${inner}
    </div>
  `;
}

