/**
 * Complete self-contained dashboard navigation handler functions.
 *
 * These handlers serialize into the iframe runtime. They switch the visible
 * work surface by toggling the data-state attribute on the workspace
 * containers that `render()` emits, without re-rendering.
 */

const CATEGORY_WORKSPACE_KEY = "data-tool-category";

function findElementByAttribute(
  document: unknown,
  attr: string,
  value?: string
): Element | null {
  const doc = document as {
    querySelector: (selector: string) => Element | null;
    querySelectorAll: (selector: string) => NodeListOf<Element>;
  };

  if (typeof doc.querySelector !== "function") return null;
  if (value !== undefined) {
    const selector = `[${attr}="${value}"]`;
    const match = doc.querySelector(selector);
    return match ?? null;
  }
  const all = typeof doc.querySelectorAll === "function"
    ? doc.querySelectorAll(`[${attr}]`)
    : null;
  return all && all.length > 0 ? all[0] : null;
}

function setDataState(element: Element | null, state: string): void {
  if (!element) return;
  const el = element as Element & { dataset: Record<string, string> };
  el.dataset.state = state;
}

function openDashboard(document: unknown): void {
  setDataState(findElementByAttribute(document, "data-role", "tool-library"), "closed");
  setDataState(findElementByAttribute(document, "data-role", "tool-space-dialog"), "closed");
  const json = findElementByAttribute(document, "data-role", "tool-workspace");
  setDataState(json, "closed");

  for (const cat of ["text", "data", "seo", "images", "social"]) {
    setDataState(
      findElementByAttribute(document, "data-role", "tool-category-workspace")
        ? (document as {
            querySelector: (s: string) => Element | null;
          }).querySelector(`[data-role="tool-category-workspace"][${CATEGORY_WORKSPACE_KEY}="${cat}"]`)
        : null,
      "closed"
    );
  }
}

function openCategory(document: unknown, category: string): void {
  openDashboard(document);
  setDataState(
    findElementByAttribute(document, "data-role", "tool-category-workspace")
      ? (document as {
          querySelector: (s: string) => Element | null;
        }).querySelector(`[data-role="tool-category-workspace"][${CATEGORY_WORKSPACE_KEY}="${category}"]`)
      : null,
    "open"
  );
}

export function openJsonWorkspace(document: unknown): void {
  openDashboard(document);
  setDataState(findElementByAttribute(document, "data-role", "tool-workspace"), "open");
}

export function openLibrary(document: unknown): void {
  openDashboard(document);
  setDataState(findElementByAttribute(document, "data-role", "tool-library"), "open");
}

export function openPersonalSpace(document: unknown): void {
  openDashboard(document);
  setDataState(findElementByAttribute(document, "data-role", "tool-space-dialog"), "open");
}

export function openTextCategory(document: unknown): void {
  openCategory(document, "text");
}

export function openDataCategory(document: unknown): void {
  openCategory(document, "data");
}

export function openSeoCategory(document: unknown): void {
  openCategory(document, "seo");
}

export function openImagesCategory(document: unknown): void {
  openCategory(document, "images");
}

export function openSocialCategory(document: unknown): void {
  openCategory(document, "social");
}

