// /features/library/actions.ts
export function openLibrary(document: unknown): void {
  const lib = (document as { querySelector?: (s: string) => { setAttribute?: (k: string, v: string) => void } | null }).querySelector?.('[data-role="tool-library"]');
  lib?.setAttribute?.('data-state', 'open');
}

export function closeLibrary(document: unknown): void {
  const lib = (document as { querySelector?: (s: string) => { setAttribute?: (k: string, v: string) => void } | null }).querySelector?.('[data-role="tool-library"]');
  lib?.setAttribute?.('data-state', 'closed');
}

export function filterLibrarySearch(document: unknown): void {
  const win = (document as { defaultView?: { document?: Document } }).defaultView?.document;
  const doc = win ?? ((document as unknown) as Document);
  const search = (doc as Document).querySelector<HTMLInputElement>('[data-role="tool-search"]');
  const query = (search?.value ?? '').trim().toLowerCase();
  const rows = Array.from((doc as Document).querySelectorAll('[data-role="tool-library-row"]'));
  for (const row of rows) {
    const label = (row as HTMLElement).textContent?.toLowerCase() ?? '';
    (row as HTMLElement).hidden = query.length > 0 && !label.includes(query);
  }
}

