export function formatJson(document: unknown): void {
  const root = document as {
    querySelector?: (selector: string) => Element | null;
  };
  const input = root.querySelector?.('[data-role="tool-json-input"]') as
    | HTMLTextAreaElement
    | HTMLInputElement
    | null;
  const result = root.querySelector?.('[data-role="tool-json-result"]') as HTMLElement | null;
  if (!input || !result) return;

  const raw = input.value.trim();
  if (!raw) {
    result.setAttribute("data-state", "error");
    result.textContent = "Enter some JSON to format.";
    return;
  }

  try {
    const parsed: unknown = JSON.parse(raw);
    const formatted = JSON.stringify(parsed, null, 2);
    result.setAttribute("data-state", "success");
    result.textContent = formatted;
  } catch (error) {
    const message = error instanceof Error ? error.message : "Invalid JSON.";
    result.setAttribute("data-state", "error");
    result.textContent = `Could not format JSON: ${message}`;
  }
}

