export function runCategoryAction(document: unknown): void {
  const doc = document as Document | null;
  if (!doc || !doc.getElementById || !doc.querySelector) {
    return;
  }
  const workspace = doc.querySelector('[data-role="tool-category-workspace"]');
  const category = workspace ? (workspace as HTMLElement).getAttribute("data-tool-category") ?? "" : "";
  const result = doc.getElementById("tool-category-result");
  if (!result) {
    return;
  }

  const setText = (value: string) => {
    result.textContent = value;
  };

  const selectEl = doc.querySelector<HTMLSelectElement>('[data-role="tool-category-select"]');
  const inputValue = (doc.getElementById("tool-category-input") as HTMLTextAreaElement | HTMLInputElement | null)?.value ?? "";

  try {
    if (category === "text") {
      const mode = selectEl?.value === "lower" || selectEl?.value === "title" ? selectEl.value : "upper";
      const trimmed = inputValue.trim();
      if (!trimmed) {
        result.setAttribute("data-state", "error");
        setText("Enter some text to transform.");
        return;
      }
      let transformed: string;
      if (mode === "upper") {
        transformed = trimmed.toUpperCase();
      } else if (mode === "lower") {
        transformed = trimmed.toLowerCase();
      } else {
        transformed = trimmed
          .toLowerCase()
          .split(/\s+/)
          .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
          .join(" ");
      }
      const words = trimmed.split(/\s+/).filter(Boolean).length;
      const chars = trimmed.length;
      result.setAttribute("data-state", "success");
      setText(
        `${transformed}\n\nCharacters: ${chars}\nWords: ${words}\nMode: ${mode}`
      );
    } else if (category === "data") {
      const mode = selectEl?.value === "encode" || selectEl?.value === "decode" ? selectEl.value : "json";
      const trimmed = inputValue.trim();
      if (!trimmed) {
        result.setAttribute("data-state", "error");
        setText("Enter data to process.");
        return;
      }
      if (mode === "json") {
        try {
          const parsed = JSON.parse(trimmed) as unknown;
          result.setAttribute("data-state", "success");
          setText(JSON.stringify(parsed, null, 2));
        } catch (err) {
          const message = err instanceof Error ? err.message : "Invalid JSON";
          result.setAttribute("data-state", "error");
          setText(`Invalid JSON: ${message}`);
        }
        return;
      }
      if (mode === "encode") {
        result.setAttribute("data-state", "success");
        setText(encodeURIComponent(trimmed));
        return;
      }
      try {
        const decoded = decodeURIComponent(trimmed.replace(/\+/g, " "));
        result.setAttribute("data-state", "success");
        setText(decoded);
      } catch {
        result.setAttribute("data-state", "error");
        setText("Could not decode the query text.");
      }
    } else if (category === "seo") {
      const trimmed = inputValue.trim();
      if (!trimmed.toLowerCase().includes("<html") && !trimmed.toLowerCase().includes("<head") && !trimmed.toLowerCase().includes("<title")) {
        result.setAttribute("data-state", "error");
        setText("Paste an HTML document to analyze.");
        return;
      }
      const titleMatch = trimmed.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
      const title = titleMatch ? titleMatch[1].trim() : "";
      const descMatch = trimmed.match(/<meta[^>]*name=["']description["'][^>]*content=["']([\s\S]*?)["']/i)
        ?? trimmed.match(/<meta[^>]*content=["']([\s\S]*?)["'][^>]*name=["']description["']/i);
      const description = descMatch ? descMatch[1].trim() : "";
      const headingCount = (trimmed.match(/<h[1-6][^>]*>/gi) ?? []).length;
      const linkCount = (trimmed.match(/<a\s[^>]*href=["'][^"']+["']/gi) ?? []).length;
      const images = trimmed.match(/<img[^>]*>/gi) ?? [];
      const withAlt = images.filter((tag) => /\balt=["'][^"']*["']/i.test(tag)).length;
      const altPercent = images.length === 0 ? 100 : Math.round((withAlt / images.length) * 100);
      result.setAttribute("data-state", "success");
      setText(
        [
          `Title: ${title || "(missing)"}`,
          `Description: ${description || "(missing)"}`,
          `Headings: ${headingCount}`,
          `Links: ${linkCount}`,
          `Images: ${images.length} (alt coverage ${altPercent}%)`,
        ].join("\n")
      );
    } else if (category === "images") {
      const trimmed = inputValue.trim();
      if (!trimmed) {
        result.setAttribute("data-state", "error");
        setText("Paste a data URL or SVG markup to inspect.");
        return;
      }
      if (/^data:([^,]+),/.test(trimmed)) {
        const mime = trimmed.match(/^data:([^,;]+)[;,]/)?.[1] ?? "unknown";
        const sizeBytes = Math.round(trimmed.length * 0.75);
        result.setAttribute("data-state", "success");
        setText(`Type: ${mime}\nApprox size: ${sizeBytes} bytes`);
      } else if (trimmed.toLowerCase().startsWith("<svg")) {
        const widthMatch = trimmed.match(/width\s*=\s*["'](\d+(?:\.\d+)?)["']/i);
        const heightMatch = trimmed.match(/height\s*=\s*["'](\d+(?:\.\d+)?)["']/i);
        const viewBox = trimmed.match(/viewBox\s*=\s*["']([\d.\s-]+)["']/i);
        const lines = ["Type: SVG"];
        if (widthMatch && heightMatch) {
          lines.push(`Dimensions: ${widthMatch[1]} × ${heightMatch[1]}`);
        } else if (viewBox) {
          lines.push(`ViewBox: ${viewBox[1].trim()}`);
        }
        lines.push(`Size: ${trimmed.length} characters`);
        result.setAttribute("data-state", "success");
        setText(lines.join("\n"));
      } else {
        result.setAttribute("data-state", "error");
        setText("Provide a data URL (data:…) or SVG markup starting with <svg.");
      }
    } else if (category === "social") {
      let title = (doc.querySelector<HTMLInputElement>('[data-role="tool-category-title"]')?.value ?? "").trim();
      let description = (doc.querySelector<HTMLInputElement>('[data-role="tool-category-description"]')?.value ?? "").trim();
      let url = (doc.querySelector<HTMLInputElement>('[data-role="tool-category-url"]')?.value ?? "").trim();
      if (!title && !description && !url && inputValue) {
        try {
          const parsed = JSON.parse(inputValue) as unknown;
          if (parsed && typeof parsed === "object") {
            const obj = parsed as Record<string, unknown>;
            title = typeof obj.title === "string" ? obj.title.trim() : title;
            description = typeof obj.description === "string" ? obj.description.trim() : description;
            url = typeof obj.url === "string" ? obj.url.trim() : url;
          } else {
            throw new Error("not an object");
          }
        } catch {
          result.setAttribute("data-state", "error");
          setText("Fill the title/description/url fields, or paste a JSON object with those keys.");
          return;
        }
      }
      if (!title || !url) {
        result.setAttribute("data-state", "error");
        setText("A title and URL are required for the preview.");
        return;
      }
      const titleChars = title.length;
      const descChars = description.length;
      const hostname = (() => {
        try {
          return new URL(url).hostname;
        } catch {
          return url;
        }
      })();
      result.setAttribute("data-state", "success");
      setText(
        [
          `Site: ${hostname}`,
          `Title: ${title} (${titleChars} chars)`,
          `Description: ${description || "(none)"} (${descChars} chars)`,
          `URL: ${url}`,
          "Preview built locally — no network request.",
        ].join("\n")
      );
    } else {
      result.setAttribute("data-state", "error");
      setText("Unknown category workspace.");
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unexpected error";
    result.setAttribute("data-state", "error");
    setText(message);
  }
}

export function backToDashboard(document: unknown): void {
  const doc = document as Document | null;
  if (!doc || !doc.querySelector) {
    return;
  }
  const workspace = doc.querySelector('[data-role="tool-category-workspace"]');
  if (workspace) {
    workspace.setAttribute("hidden", "hidden");
  }
  const dashboard = doc.querySelector('[data-role="tool-dashboard"]');
  if (dashboard) {
    dashboard.removeAttribute("hidden");
  }
}

