        var su = sel("tool-category-url");
        if (!st && !sd && !su && (inputValue || "")) {
          try {
            var sp = JSON.parse(inputValue);
            if (sp && typeof sp === "object") {
              if (typeof sp.title === "string") st = sp.title.trim();
              if (typeof sp.description === "string") sd = sp.description.trim();
              if (typeof sp.url === "string") su = sp.url.trim();
            } else { throw new Error("not object"); }
          } catch (err) { result.setAttribute("data-state", "error"); setText("Fill the fields, or paste a JSON object with title/description/url."); return; }
        }
        if (!st || !su) { result.setAttribute("data-state", "error"); setText("A title and URL are required for the preview."); return; }
        var host;
        try { host = new URL(su).hostname; } catch (err) { host = su; }
        result.setAttribute("data-state", "success");
        setText("Site: " + host + "\\nTitle: " + st + " (" + st.length + " chars)" + "\\nDescription: " + (sd || "(none)") + " (" + sd.length + " chars)" + "\\nURL: " + su + "\\nPreview built locally — no network request.");
      } else {
        result.setAttribute("data-state", "error");
        setText("Unknown category workspace.");
      }
    } catch (err) {
      result.setAttribute("data-state", "error");
      setText(err && err.message ? err.message : "Unexpected error");
    }
  }`,
  backToDashboard: `({ document }) => {
    var workspace = document.querySelector('[data-role="tool-category-workspace"]');
    if (workspace) { workspace.setAttribute("hidden", "hidden"); }
    var dashboard = document.querySelector('[data-role="tool-dashboard"]');
    if (dashboard) { dashboard.removeAttribute("hidden"); }
  }`,
};

