import { defineRenderOnLoadActions } from "@anikitenko/fdo-sdk";
import type { RenderOnLoadActionBinding, RenderOnLoadActionHandler } from "@anikitenko/fdo-sdk";
import { dashboardActionHandlers } from "./features/dashboard/actions";
import { libraryActionHandlers } from "./features/library/actions";
import { jsonActionHandlers } from "./features/json/actions";
import { spaceActionHandlers } from "./features/space/actions";
import { categoryActionHandlers } from "./features/category/actions";

type HandlerMap = Record<string, RenderOnLoadActionHandler>;

function mergeHandlers(...maps: HandlerMap[]): HandlerMap {
  const merged: HandlerMap = {};
  for (const map of maps) {
    for (const [key, value] of Object.entries(map)) {
      merged[key] = value;
    }
  }
  return merged;
}

const handlers = mergeHandlers(
  dashboardActionHandlers,
  libraryActionHandlers,
  jsonActionHandlers,
  spaceActionHandlers,
  categoryActionHandlers
);

const bindings: RenderOnLoadActionBinding[] = [
  { selector: "[data-role=tool-library-button]", event: "click", handler: "openLibrary", preventDefault: true },
  { selector: "[data-role=tool-space-button]", event: "click", handler: "openSpace", preventDefault: true },
  { selector: "[data-role=tool-card-json]", event: "click", handler: "openJsonWorkspace", preventDefault: true },
  { selector: "[data-role=tool-open-json]", event: "click", handler: "openJsonWorkspace", preventDefault: true },
  { selector: "[data-role=tool-library-close]", event: "click", handler: "closeLibrary", preventDefault: true },
  { selector: "[data-role=tool-search]", event: "input", handler: "filterLibrarySearch", passive: true },
  { selector: "[data-role=tool-back-dashboard]", event: "click", handler: "backToDashboard", preventDefault: true },
  { selector: "[data-role=tool-format-json]", event: "click", handler: "formatJson", preventDefault: true },
  { selector: "[data-role=tool-space-close]", event: "click", handler: "closeSpace", preventDefault: true },
  { selector: "[data-role=tool-category-back]", event: "click", handler: "backToDashboard", preventDefault: true },
  { selector: "[data-role=tool-category-action]", event: "click", handler: "runCategoryAction", preventDefault: true },
];

export function createRenderOnLoadActions() {
  return defineRenderOnLoadActions({
    handlers,
    bindings,
    description: "Web Tools Workbench declarative UI actions",
    language: "javascript",
  });
}

