import assert from "node:assert/strict";
import { render, renderCategory } from "./render";

test("dashboard shows the workbench title and required interactive targets", () => {
  const html = render();
  assert.match(html, /data-role="tool-workbench"/);
  assert.match(html, /data-role="tool-brand"/);
  assert.match(html, /data-role="tool-dashboard"/);
  assert.match(html, /data-role="tool-library-button"/);
  assert.match(html, /data-role="tool-space-button"/);
  assert.match(html, /data-role="tool-card-json"/);
  assert.match(html, /data-role="tool-card-text"/);
  assert.match(html, /data-role="tool-card-data"/);
  assert.match(html, /data-role="tool-card-seo"/);
  assert.match(html, /data-role="tool-card-images"/);
  assert.match(html, /data-role="tool-card-social"/);
  assert.match(html, /<h1[^>]*>Web Tools Workbench<\/h1>/i);
});

test("JSON formatter workspace exposes input, format button and result", () => {
  const html = render({ tool: "json" });
  assert.match(html, /data-role="tool-workspace"/);
  assert.match(html, /data-role="tool-back-dashboard"/);
  assert.match(html, /data-role="tool-json-input"/);
  assert.match(html, /data-role="tool-format-json"/);
  assert.match(html, /data-role="tool-json-result"/);
});

test("each category workspace renders its stable category value and controls", () => {
  for (const category of ["text", "data", "seo", "images", "social"] as const) {
    const html = renderCategory(category);
    assert.match(html, /data-role="tool-category-workspace"/);
    assert.match(html, new RegExp(`data-tool-category="${category}"`));
    assert.match(html, /data-role="tool-category-input"/);
    assert.match(html, /data-role="tool-category-action"/);
    assert.match(html, /data-role="tool-category-result"/);
    assert.match(html, /data-role="tool-category-back"/);
  }
});

