  assert.equal(upper.output, "ABC DEF");
  assert.equal(upper.details?.characters, 7);
  assert.equal(upper.details?.words, 2);

  const lower = applyTextTransform("AbC", "lower") as { status: string; output: string };
  assert.equal(lower.status, "success");
  assert.equal(lower.output, "abc");

  const title = applyTextTransform("the quick fox", "title") as { status: string; output: string };
  assert.equal(title.status, "success");
  assert.equal(title.output, "The Quick Fox");
});

