test("analyzeHtml reports title, description, headings, links, alt coverage", () => {
  const html = `
    <title>Page Title</title>
    <meta name="description" content="A description" />
    <h1>First</h1>
    <h2>Second</h2>
    <a href="https://example.com">Link</a>
    <a href="https://example.com/2">No text</a>
    <img src="a.png" alt="alt text" />
    <img src="b.png" />
  `;
  const result = analyzeHtml(html) as { status: string; details?: Record<string, string | number> };
  assert.equal(result.status, "success");
  assert.equal(result.details?.title, "Page Title");
  assert.equal(result.details?.description, "A description");
  assert.equal(result.details?.headings, 2);
  assert.equal(result.details?.links, 2);
  assert.equal(result.details?.images, 2);
  assert.equal(result.details?.altCoverage, "1/2");
});

test("analyzeHtml errors on empty input", () => {
  const result = analyzeHtml("  ");
  assert.equal(result.status, "error");
});

test("inspectMedia reports data URL type and size", () => {
  const dataUrl =
    "data:image/svg+xml;base64," + Buffer.from("<svg xmlns='http://www.w3.org/2000/svg'></svg>").toString("base64");
  const result = inspectMedia(dataUrl) as { status: string; details?: Record<string, string | number> };
